/** Source of truth for stocks and reserves. */

export interface InventoryServiceClient {
  getStock(request: GetStockRequest): Observable<Stock>;

  listStocks(request: ListStocksRequest): Observable<StockList>;

  setStock(request: SetStockRequest): Observable<Stock>;

  adjustStock(request: AdjustStockRequest): Observable<Stock>;

  /**
   * Saga steps, called by orders-service only. All three are idempotent by
   * idempotency_key. Commit/Release return snapshots plus replayed, not ALREADY_FINAL.
   * Release after Commit is a no-op; fresh Commit after Release/expiry is rejected.
   */

  reserve(request: ReserveRequest): Observable<ReserveResponse>;

  commit(request: CommitRequest): Observable<CommitResponse>;

  release(request: ReleaseRequest): Observable<ReleaseResponse>;
}

/** Source of truth for stocks and reserves. */

export interface InventoryServiceController {
  getStock(request: GetStockRequest): Promise<Stock> | Observable<Stock> | Stock;

  listStocks(request: ListStocksRequest): Promise<StockList> | Observable<StockList> | StockList;

  setStock(request: SetStockRequest): Promise<Stock> | Observable<Stock> | Stock;

  adjustStock(request: AdjustStockRequest): Promise<Stock> | Observable<Stock> | Stock;

  /**
   * Saga steps, called by orders-service only. All three are idempotent by
   * idempotency_key. Commit/Release return snapshots plus replayed, not ALREADY_FINAL.
   * Release after Commit is a no-op; fresh Commit after Release/expiry is rejected.
   */

  reserve(request: ReserveRequest): Promise<ReserveResponse> | Observable<ReserveResponse> | ReserveResponse;

  commit(request: CommitRequest): Promise<CommitResponse> | Observable<CommitResponse> | CommitResponse;

  release(request: ReleaseRequest): Promise<ReleaseResponse> | Observable<ReleaseResponse> | ReleaseResponse;
}

export function InventoryServiceControllerMethods() {
  return function (constructor: Function) {
    const grpcMethods: string[] = ["getStock", "listStocks", "setStock", "adjustStock", "reserve", "commit", "release"];
    for (const method of grpcMethods) {
      const descriptor: any = Reflect.getOwnPropertyDescriptor(constructor.prototype, method);
      GrpcMethod("InventoryService", method)(constructor.prototype[method], method, descriptor);
      Object.defineProperty(constructor.prototype, method, descriptor);
    }
    const grpcStreamMethods: string[] = [];
    for (const method of grpcStreamMethods) {
      const descriptor: any = Reflect.getOwnPropertyDescriptor(constructor.prototype, method);
      GrpcStreamMethod("InventoryService", method)(constructor.prototype[method], method, descriptor);
      Object.defineProperty(constructor.prototype, method, descriptor);
    }
  };
}

